from marshmallow import Schema, fields, ValidationError, validates, EXCLUDE


class SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(missing="free")
    age = fields.Integer(validate=lambda n: 16 <= n <= 120, required=False)

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("plan")
    def validate_plan(self, value):
        if value not in ("free", "pro", "team"):
            raise ValidationError("Plan must be one of 'free', 'pro', or 'team'.")


def validate_signup(data: dict) -> dict:
    """Validate sign-up data, returning cleaned dict or raising ValueError with messages attribute."""
    schema = SignupSchema()
    try:
        return schema.load(data)
    except ValidationError as err:
        exc = ValueError("invalid signup data")
        exc.messages = err.messages
        raise exc

from typing import list, dict, Optional
import pkg_resources


def dependency_report(names: list[str]) -> dict[str, Optional[str]]:
    """Map each distribution name to its installed version string or None if not installed."""
    # Build a dict of installed distributions keyed case-insensitively for efficient lookup
    installed = {dist.project_name.lower(): dist.version for dist in pkg_resources.working_set}
    result = {}
    for name in names:
        version = installed.get(name.lower())
        result[name] = version
    return result

import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """
    Create an httpx.Client for base_url that sends all requests (http and https)
    through the HTTP proxy at proxy_url, with a 5-second timeout and a fixed User-Agent header.
    """
    proxies = {
        "http://": proxy_url,
        "https://": proxy_url,
    }
    headers = {
        "User-Agent": "inventory-sync/1.0",
    }
    timeout = 5.0

    return httpx.Client(base_url=base_url, proxies=proxies, headers=headers, timeout=timeout)

